edits.old:
$city_sounds = {
	if sound_on = 1:
		if city_form ! 1000:
			if noble_status = 1 or brand_reputation >= 5:
				$toplay = 'honor'
			elseif $estate = 'slum_house':
				$toplay = 'poor'
			else
				$toplay = 'citizen'
			end
		else
			$toplay = 'city'
		end
	end
	dynamic $play_music
}

edits.new:
! JO9 MOD START CITY_SETTINGS_BGM_KEEP_20261111
$city_sounds = {
	if sound_on = 1:
		if city_form ! 1000 or $toplay = '' or $toplay = 'city':
			if noble_status = 1 or brand_reputation >= 5:
				$toplay = 'honor'
			elseif $estate = 'slum_house':
				$toplay = 'poor'
			else
				$toplay = 'citizen'
			end
		end
	end
	dynamic $play_music
}
! JO9 MOD END CITY_SETTINGS_BGM_KEEP_20261111
